functions.sourceIdentity:
export function sourceIdentity(source: string): string {
  requireInput(source.length > 0 && !isAbsolute(source) && !source.includes('\\') && !source.split('/').includes('..') && !/[\u0000-\u001f\u007f-\u009f]/.test(source) && !/^[a-z]:/i.test(source), 'Source must be a root-relative path without traversal');
  return source.replace(/^\.\//, '');
}

functions.affected:
export async function affected(options: AffectedOptions) {
  verificationInput([], options); const verification = new Verification(options); const settings = verification.options;
  const store = new Store(settings); const items = await store.all(); const native = RelationshipGraph.fromItems(items); const graph = new RelationshipGraph(native.nodes(), native.edges().map(edge => edge.kind === 'parent' ? { ...edge, source: edge.target, target: edge.source } : edge)); const rows: Impact[] = []; let sourceComplete = true;
  const depth = settings.depth ?? 2; const limit = settings.limit ?? 100;
  const paths = settings.changed?.map(sourceIdentity); let checked = 0;
  requireInput(items.length <= 10_000, 'Impact scope exceeds 10000 items');
  for (const item of items) {
    const seen = new Set<string>();
    for (const [index, citation] of (verificationState(item.evidence_state, verification)?.citations ?? []).entries()) {
      if (paths !== undefined) {
        const parsed = citationSchema.safeParse(citation);
        if (parsed.success && parsed.data.provenance.item === item.id && !paths.includes(parsed.data.descriptor.source) && !seen.has(parsed.data.id)) { seen.add(parsed.data.id); continue; }
      }
      checked++;
      requireInput(checked <= 10_000, 'Impact scope exceeds 10000 citations');
      const result = await checkCitation(citation, settings, verification, { item: item.id, index, seen });
      if (result.code !== 'canceled') verification.receipt.checked++;
      if (result.freshness === 'unknown') sourceComplete = false;
      if (result.freshness === 'current') continue;
      const closure = graph.closure(item.id, { direction: 'incoming', kinds: ['parent', 'depends_on', 'blocked_by'], maxDepth: depth, limit });
      if (closure.meta.truncated) sourceComplete = false;
      for (const target of [item.id, ...closure.value]) {
        const path = target === item.id ? [item.id] : graph.shortestPath(item.id, target, { direction: 'incoming', kinds: ['parent', 'depends_on', 'blocked_by'], maxDepth: depth, limit }).value;
        rows.push({ item: target, type: items.find(entry => entry.id === target)!.type, evidenceItem: item.id, citation: result.citation, ...(result.code === undefined ? {} : { code: result.code, remedy: result.remedy, citationIndex: result.citationIndex }), resolution: result.resolution, freshness: result.freshness, path });
      }
    }
  }
  return packet(rows, { items: items.length, citations: checked, depth, changed: paths, traversalLimit: limit }, settings.budget, sourceComplete && !verification.canceled() && verification.receipt.foreignItems === 0, verification.finish());
}

functions.prepare:
async function prepare(item: string, source: string, options: CiteOptions, author: string, sourceSnapshot?: SourceSnapshot, sectionScoped = false): Promise<Citation> {
  const selector = parseSelector(options.selector);
  const identity = sourceIdentity(source); const provider = options.provider ?? (selector.kind === 'pointer' ? 'json' : 'file');
  requireInput(provider !== 'json' || selector.kind === 'pointer', 'JSON sources require a pointer selector');
  const read = sourceSnapshot ?? await snapshot(provider, identity, options); const selected = select(read.text, selector);
  const descriptor: Descriptor = { provider, source: identity, revision: read.revision, selector, ...(selector.kind === 'pointer' ? { jsonEncoding: 'source-bytes-v1' as const } : { anchor: anchor(read.text, selected, selector.kind === 'heading' || sectionScoped) }) };
  if (descriptor.anchor !== undefined) resolveFragment(read.text, descriptor);
  const fragmentDigest = digest(selected.text);
  return parseCitation({ id: `ev-${digest(JSON.stringify([item, descriptor, fragmentDigest])).slice(0, 24)}`, descriptor, fragmentDigest, ...(options.retain === true ? { retained: Buffer.from(selected.text).toString('base64') } : {}), provenance: { item, author, at: new Date().toISOString() }, reviews: [] }, item);
}

functions.snapshot:
export async function snapshot(provider: string, source: string, options: EvidenceOptions): Promise<SourceSnapshot> {
  const adapter = [...(options.adapters ?? []), fileAdapter, jsonAdapter].find(entry => entry.provider === provider);
  if (adapter === undefined) throw new EvidenceError('unsupported', 'Source provider is unavailable', 'Supply the typed adapter that owns this provider');
  const maxBytes = options.maxBytes ?? 1_048_576; const timeoutMs = options.timeoutMs ?? 5000;
  requireInput(Number.isSafeInteger(maxBytes) && maxBytes > 0 && maxBytes <= 16_777_216 && Number.isSafeInteger(timeoutMs) && timeoutMs > 0 && timeoutMs <= 60_000, 'Invalid source size or deadline bounds');
  const controller = new AbortController(); const signal = options.signal === undefined ? controller.signal : AbortSignal.any([controller.signal, options.signal]);
  let timer: ReturnType<typeof setTimeout>;
  const timeout = new Promise<never>((_resolve, reject) => { timer = setTimeout(() => { controller.abort(); reject(new EvidenceError('timeout', 'Source read deadline exceeded', 'Retry with an available bounded source')); }, timeoutMs); });
  const read = async (): Promise<SourceSnapshot> => {
    signal.throwIfAborted();
    const result = await Promise.race([adapter.read(sourceIdentity(source), { root: options.root ?? '.', maxBytes, signal }), timeout]);
    signal.throwIfAborted();
    requireInput(typeof result === 'object' && result !== null && typeof result.text === 'string' && Buffer.byteLength(result.text) <= maxBytes && result.revision === digest(result.text), 'Adapter must return one size-bounded content digest revision');
    return Object.freeze({ text: result.text, revision: result.revision });
  };
  /** Abort promptly even when a trusted adapter does not cooperate with its signal. */
  let abort: () => void;
  const canceled = new Promise<never>((_resolve, reject) => { abort = () => reject(options.signal?.aborted === true ? new EvidenceError('canceled', 'Source read was canceled', 'Retry the check with a live signal; this receipt is incomplete') : new EvidenceError('timeout', 'Source read deadline exceeded', 'Retry with an available bounded source')); signal.addEventListener('abort', abort, { once: true }); });
  return Promise.race([read(), canceled]).catch(error => { if (options.signal?.aborted === true) throw new EvidenceError('canceled', 'Source read was canceled', 'Retry the check with a live signal; this receipt is incomplete'); throw sourceError(error); }).finally(() => { clearTimeout(timer); signal.removeEventListener('abort', abort); });
}

functions.read:
async read(provider: string, source: string): Promise<SourceSnapshot> {
  if (this.canceled()) throw new EvidenceError('canceled', 'Verification was canceled', 'Retry the check with a live signal; this receipt is incomplete');
  const identity = sourceIdentity(source); const key = JSON.stringify([provider, identity]);
  let read = this.reads.get(key);
  if (read === undefined) {
    if (this.reads.size >= MAX_ENTRIES) throw new EvidenceError('size', 'Verification source limit reached', 'Split the check into batches of at most 10000 sources');
    this.receipt.sources++;
    read = this.load(provider, identity); this.reads.set(key, read);
  }
  return read;
}

functions.writeEvidence:
function writeEvidence(document: ItemDocument, value: EvidenceState, observation: string, author: string): string[] {
  const owned = new Set((document.metadata.files ?? []).map(artifactKey));
  const files = [...new Set(value.citations.filter(entry => ['file', 'json'].includes(entry.descriptor.provider)).map(entry => entry.descriptor.source))].map(source => ({ path: source, scope: 'project' as const, note: 'pm-evidence source identity relative to caller-selected root' })).filter(file => !owned.has(artifactKey(file)));
  Object.assign(document.metadata, { evidence_state: JSON.stringify(value), ...(files.length > 0 ? { files: [...document.metadata.files ?? [], ...dedupeLinkedArtifacts(files)] } : {}), comments: [...document.metadata.comments ?? [], { text: parseAnnotationTextInput(observation), author, created_at: nowIso() }] });
  return ['evidence_state', 'comments', ...(files.length > 0 ? ['files'] : [])];
}

functions.rootIdentityGuard:
export function sourceIdentity(source: string, provider = 'file'): string {
  requireInput(typeof source === 'string' && source.length > 0 && !isAbsolute(source) && !source.includes('\\') && !/[\u0000-\u001f\u007f-\u009f]/.test(source) && !/^[a-z]:/i.test(source), 'Source must be a root-relative path without traversal');
  if (provider !== 'file' && provider !== 'json') {
    requireInput(!source.split('/').includes('..'), 'Custom source identities cannot contain traversal');
    return source.replace(/^\.\//, '');
  }
  const identity = posix.normalize(source).replace(/\/$/, '');
  requireInput(identity !== '.' && identity !== '..' && !identity.startsWith('../') && !/^[a-z]:/i.test(identity), 'Source must name a path inside the selected root');
  return identity;
}
